(function(){'use strict';
const profiles={"KYIV":{"name":"Kyivstar","year":"1994","sector":{"uk":"Мобільний зв'язок","en":"Telecommunications"},"history":{"uk":"Історія оператора почалася у 1994 році під назвою Bridge. У 1997 році запрацювала мережа GSM; згодом компанія розвивала мобільний інтернет, 3G та 4G. У 2025 році створено публічну холдингову компанію Kyivstar Group.","en":"The operator traces its origins to Bridge in 1994. Its GSM network launched in 1997, followed by mobile internet, 3G and 4G. The listed Kyivstar Group holding company was incorporated in 2025."},"source":"https://kyivstar.ua/about","branches":{"uk":["Мобільний зв’язок","Домашній інтернет","Цифрові сервіси: Київстар ТБ, Helsi, Kyivstar.Tech"],"en":["Mobile services","Home internet","Digital services: Kyivstar TV, Helsi, Kyivstar.Tech"]},"recognition":{"uk":"Впізнаваність забезпечили масове поширення мобільного зв’язку в Україні, мережа GSM і розвиток мобільного інтернету. Вихід групи на Nasdaq у 2025 році став окремою віхою.","en":"Widespread mobile adoption in Ukraine, the GSM network and mobile internet built brand recognition. The group's 2025 Nasdaq listing was a separate milestone."},"milestones":[{"year":"1994","uk":"Початок історії оператора","en":"Operator's origins"},{"year":"1997","uk":"Перший дзвінок у мережі","en":"First network call"},{"year":"2015","uk":"Запуск 3G","en":"3G network launch"},{"year":"2018","uk":"Запуск 4G","en":"4G network launch"},{"year":"2025","uk":"Лістинг групи на Nasdaq","en":"Group lists on Nasdaq"}]},"MHPC.L":{"name":"MHP","year":"1998","sector":{"uk":"Агропромисловість","en":"Agribusiness"},"history":{"uk":"Юрій Косюк розпочав бізнес із підприємства з виробництва круп і комбікормів у 1998 році. З 1999 року група розвивала птахівництво та власне виробництво кормів. Згодом МХП розширився у м’ясопереробку, кулінарію та міжнародні ринки.","en":"Yuriy Kosyuk began with a groats and feed producer in 1998. From 1999, the group developed poultry farming and its own feed operations. MHP later expanded into meat processing, prepared foods and international markets."},"source":"https://www.mhp.com.ua/en/pro-kompaniiu","branches":{"uk":["Птахівництво","Корми та зернові","Готові харчові продукти"],"en":["Poultry","Feed and grain","Prepared foods"]},"recognition":{"uk":"Впізнаваність забезпечила «Наша Ряба», запущена у 2002 році. Власні корми, птахокомплекси, переробка та мережі продажу допомогли масштабувати виробництво. Perutnina Ptuj та UVESA розширили присутність у Європі.","en":"Nasha Ryaba, introduced in 2002, helped establish consumer recognition. Feed production, poultry facilities, processing and retail networks supported expansion. Perutnina Ptuj and UVESA extended its European presence."},"milestones":[{"year":"1998","uk":"Придбання Миронівського заводу круп і комбікормів","en":"Acquisition of the Myronivka groats and feed plant"},{"year":"1999","uk":"Початок виробництва курятини","en":"Start of poultry production"},{"year":"2002","uk":"Запуск бренду «Наша Ряба»","en":"Launch of Nasha Ryaba"},{"year":"2006","uk":"Запуск заводу м’ясопереробки «Легко!»","en":"Launch of Lehko! meat processing plant"},{"year":"2007","uk":"Перша лінія Миронівського птахокомплексу","en":"First Myronivka poultry complex line"},{"year":"2008","uk":"Лістинг у Лондоні","en":"London listing"},{"year":"2012","uk":"Перший біогазовий проєкт","en":"First biogas project"},{"year":"2019","uk":"Придбання Perutnina Ptuj","en":"Acquisition of Perutnina Ptuj"},{"year":"2025","uk":"Приєднання іспанської групи UVESA","en":"Spanish UVESA group joins MHP"}]},"FXPO.L":{"name":"Ferrexpo","year":"1960 / 2007","sector":{"uk":"Гірничодобувна промисловість","en":"Mining"},"history":{"uk":"Витоки — розробка родовища на Полтавщині у 1960-х. У 1970 році запрацював комбінат, у 1977 — виробництво окатків. Ferrexpo вийшла на Лондонську біржу у 2007 році.","en":"Its roots lie in mining in the Poltava region in the 1960s. The plant began operating in 1970 and pellet production in 1977. Ferrexpo listed in London in 2007."},"source":"https://www.ferrexpo.com/about-ferrexpo/","branches":{"uk":["Видобуток залізної руди","Збагачення руди","Виробництво залізорудних окатків"],"en":["Iron ore mining","Ore beneficiation","Iron ore pellet production"]},"recognition":{"uk":"Компанія відома не масовим споживчим брендом, а постачанням залізорудних окатків для металургії. Власні родовища та переробка на Полтавщині є основою бізнесу.","en":"Ferrexpo is known in the steel industry rather than as a consumer brand. Its Ukrainian mines and processing operations support its iron ore pellet business."},"milestones":[{"year":"1960","uk":"Початок розвитку залізорудного родовища","en":"Origins of iron ore development"},{"year":"1970","uk":"Запуск виробництва концентрату","en":"Concentrate production starts"},{"year":"1977","uk":"Початок виробництва окатків","en":"Pellet production starts"},{"year":"2007","uk":"Лістинг у Лондоні","en":"London listing"}]},"AST.WA":{"name":"Astarta","year":"1993","sector":{"uk":"Агропромисловість","en":"Agribusiness"},"history":{"uk":"Віктор Іванчик заснував Астарту-Київ. Бізнес починався з постачання ресурсів цукровим заводам, а потім перейшов до виробництва цукру, сільського господарства та переробки сої.","en":"Viktor Ivanchyk founded Astarta-Kyiv. It began supplying resources to sugar mills and expanded into sugar production, farming and soybean processing."},"source":"https://astartaholding.com/en/history-and-development/","branches":{"uk":["Цукрове виробництво","Рослинництво","Переробка сої","Молочне тваринництво"],"en":["Sugar production","Crop farming","Soybean processing","Dairy farming"]},"recognition":{"uk":"Впізнаваність у галузі принесли цукрові заводи й вертикальна інтеграція: вирощування сировини, переробка та збут. Згодом бізнес диверсифікувався.","en":"Sugar mills and vertical integration, from growing crops to processing and selling them, built its industry profile. The business later diversified."},"milestones":[{"year":"1993","uk":"Заснування Астарти","en":"Astarta founded"},{"year":"2006","uk":"Лістинг у Варшаві","en":"Warsaw listing"},{"year":"2013","uk":"Запуск біоенергетичного комплексу","en":"Bioenergy complex launch"},{"year":"2014","uk":"Розвиток переробки сої","en":"Soybean processing expansion"}]},"KER.WA":{"name":"Kernel","year":"1995","sector":{"uk":"Агропромисловість","en":"Agribusiness"},"history":{"uk":"Компанія розпочала з торгівлі сільськогосподарською продукцією. Згодом розвинула переробку соняшнику, зерновий експорт та портову логістику.","en":"The business began in agricultural commodity trading and grew into sunflower processing, grain exports and port logistics."},"source":"https://www.kernel.ua/wp-content/uploads/2018/10/Kernel_FY2018_Annual_Presentation.pdf","branches":{"uk":["Соняшникова олія","Зерновий експорт","Аграрне виробництво та логістика"],"en":["Sunflower oil","Grain exports","Farming and logistics"]},"recognition":{"uk":"Модель розвитку об’єднала закупівлю зерна, виробництво олії, елеватори та експортні термінали. Власна інфраструктура дозволила масштабувати експорт українських аграрних товарів, а бутильована соняшникова олія зробила бізнес впізнаваним серед покупців.","en":"Its business model connects grain procurement, oil processing, silos and export terminals. This infrastructure supported large-scale agricultural exports, while bottled sunflower oil helped establish consumer recognition."},"milestones":[{"year":"1995","uk":"Початок експорту зерна та олійних культур","en":"Grain and oilseed export business begins"},{"year":"2002","uk":"Придбання олійноекстракційного заводу на Полтавщині","en":"Acquisition of a sunflower crushing plant in Poltava"},{"year":"2005","uk":"Реєстрація Kernel Holding S.A. у Люксембурзі","en":"Kernel Holding S.A. incorporated in Luxembourg"},{"year":"2007","uk":"Лістинг у Варшаві","en":"Warsaw listing"},{"year":"2007","uk":"Розширення бізнесу бутильованої соняшникової олії","en":"Expansion into bottled sunflower oil"},{"year":"2011","uk":"Розширення земельних і складських активів","en":"Expansion of farming and storage assets"},{"year":"2017","uk":"Дебютний євробонд та розширення агроактивів","en":"Debut Eurobond and expansion of farming assets"},{"year":"2025","uk":"30 років діяльності групи","en":"Group celebrates 30 years"}]},"IMC.WA":{"name":"IMC","year":"2007","sector":{"uk":"Сільське господарство","en":"Agriculture"},"history":{"uk":"Витоки бізнесу Олександра Петрова сягають 1998 року, коли він придбав молокозавод у Кременчуці. Сучасна агрогрупа створена у 2007 році після придбання господарств на Полтавщині. Вона розширилася на Чернігівщину й Сумщину, розвиваючи вирощування зернових та олійних культур.","en":"Oleksandr Petrov’s business roots go back to a 1998 dairy acquisition in Kremenchuk. The present farming group began in 2007 through acquisitions in the Poltava region. It expanded into Chernihiv and Sumy, focusing on grain and oilseed production."},"source":"https://www.imcagro.com.ua/en/about-company/history","branches":{"uk":["Вирощування кукурудзи, пшениці та соняшнику","Зберігання зерна","Збут агропродукції"],"en":["Corn, wheat and sunflower farming","Grain storage","Agricultural sales"]},"recognition":{"uk":"ІМК відома не стільки споживчим брендом, скільки вирощуванням зернових, елеваторною мережею та застосуванням точного землеробства. У 2017 році компанія змінила назву, підкресливши нові пріоритети; у 2023 році представила довгострокову SMART GREEN STRATEGY.","en":"IMC is known primarily for grain production, storage infrastructure and precision farming rather than consumer branding. Its 2017 name change reflected a shift in priorities; in 2023 it announced the long-term SMART GREEN STRATEGY."},"milestones":[{"year":"1998","uk":"Засновник придбав Кременчуцький молокозавод (передісторія групи)","en":"Founder acquires Kremenchuk dairy plant (business roots)"},{"year":"2007","uk":"Створення агрогрупи на Полтавщині та Чернігівщині","en":"Agricultural group formed in Poltava and Chernihiv regions"},{"year":"2009","uk":"Впровадження GPS-контролю техніки","en":"GPS equipment monitoring introduced"},{"year":"2011","uk":"Лістинг у Варшаві","en":"Warsaw listing"},{"year":"2012","uk":"Розширення земельного банку та елеваторів","en":"Expansion of farmland and grain storage"},{"year":"2014","uk":"Відкриття нового елеватора","en":"New grain elevator opens"},{"year":"2016","uk":"Кредит ЄБРР для розвитку бізнесу","en":"EBRD development loan"},{"year":"2017","uk":"Перейменування на IMC S.A. та перші дивіденди","en":"Renamed IMC S.A. and first dividends"},{"year":"2023","uk":"Стратегія SMART GREEN 2033","en":"SMART GREEN 2033 strategy"},{"year":"2024","uk":"Інвестиції у власні зерновози-залізничні вагони","en":"Investment in own grain railcars"},{"year":"2025","uk":"Рекордний для компанії врожай озимої пшениці","en":"Company record winter wheat yield"}]},"KSG.WA":{"name":"KSG Agro","year":"2001 / 2010","sector":{"uk":"Сільське господарство","en":"Agriculture"},"history":{"uk":"Першим підприємством групи у 2001 році стало АТД «Дніпровський». Надалі група розширила рослинництво та свинарство. Юридичну особу KSG Agro S.A. створено у 2010 році.","en":"The group's first farm, ATD Dniprovskyi, was established in 2001. It expanded into crop and pig production. The listed legal entity dates to 2010."},"source":"https://ksgagro.com/en/agroxolding/istoriya-rozvitku","branches":{"uk":["Рослинництво","Свинарство","Виробництво кормів"],"en":["Crop farming","Pig farming","Feed production"]},"recognition":{"uk":"Група розвивала поєднання рослинництва, кормів і свинарства. Саме аграрна спеціалізація визначає її впізнаваність серед інвесторів.","en":"The group developed a combination of crop farming, feed and pig production. This agricultural focus defines its investor profile."},"milestones":[{"year":"2001","uk":"Початок діяльності першого підприємства","en":"First group farm begins operating"},{"year":"2010","uk":"Створення KSG Agro S.A.","en":"KSG Agro S.A. incorporated"},{"year":"2011","uk":"Лістинг у Варшаві","en":"Warsaw listing"}]},"AAPL":{"name":"Apple","year":"1976","sector":{"uk":"Технології","en":"Technology"},"history":{"uk":"Стів Джобс, Стів Возняк і Рональд Вейн заснували Apple для продажу персональних комп'ютерів. Apple II, Macintosh (1984) та iPhone (2007) стали ключовими етапами розвитку.","en":"Steve Jobs, Steve Wozniak and Ronald Wayne founded Apple to sell personal computers. The Apple II, Macintosh (1984) and iPhone (2007) were major milestones."},"source":"https://www.apple.com/","branches":{"uk":["iPhone та iPad","Mac","Сервіси й аксесуари"],"en":["iPhone and iPad","Mac","Services and accessories"]},"recognition":{"uk":"Macintosh популяризував графічний інтерфейс, iPod та iTunes змінили споживання музики, а iPhone і App Store створили екосистему смартфонів. Дизайн і зв’язок між пристроями стали важливими перевагами бренду.","en":"Macintosh popularized graphical interfaces, iPod and iTunes transformed music consumption, and iPhone with the App Store built a smartphone ecosystem. Design and device integration became core strengths."},"milestones":[{"year":"1976","uk":"Заснування Apple та Apple I","en":"Apple founded and Apple I"},{"year":"1977","uk":"Apple II","en":"Apple II"},{"year":"1984","uk":"Macintosh","en":"Macintosh"},{"year":"2001","uk":"iPod","en":"iPod"},{"year":"2007","uk":"iPhone","en":"iPhone"},{"year":"2008","uk":"App Store","en":"App Store"},{"year":"2010","uk":"Перший iPad","en":"First iPad"},{"year":"2020","uk":"Перехід Mac на Apple Silicon","en":"Mac transition to Apple Silicon"}]},"MSFT":{"name":"Microsoft","year":"1975","sector":{"uk":"Програмне забезпечення","en":"Software"},"history":{"uk":"Білл Гейтс і Пол Аллен почали з інтерпретатора BASIC для Altair. MS-DOS та Windows перетворили компанію на лідера ПЗ; пізніше з'явилися Azure та хмарні сервіси.","en":"Bill Gates and Paul Allen began with BASIC for the Altair. MS-DOS and Windows drove its growth, followed by Azure and cloud services."},"source":"https://www.microsoft.com/","branches":{"uk":["Windows і Microsoft 365","Azure","Ігри Xbox та корпоративне ПЗ"],"en":["Windows and Microsoft 365","Azure","Xbox gaming and enterprise software"]},"recognition":{"uk":"MS-DOS і Windows стали масовими платформами ПК, Office — стандартним робочим інструментом для багатьох організацій. Azure відкрив новий напрям зростання у хмарних обчисленнях.","en":"MS-DOS and Windows became mass-market PC platforms, while Office became a common workplace tool. Azure opened a new growth avenue in cloud computing."},"milestones":[{"year":"1975","uk":"Заснування та BASIC для Altair","en":"Founded; BASIC for Altair"},{"year":"1981","uk":"MS-DOS для IBM PC","en":"MS-DOS for IBM PC"},{"year":"1985","uk":"Windows 1.0","en":"Windows 1.0"},{"year":"1990","uk":"Microsoft Office для Windows","en":"Microsoft Office for Windows"},{"year":"2001","uk":"Xbox","en":"Xbox"},{"year":"2010","uk":"Azure","en":"Azure"},{"year":"2016","uk":"Придбання LinkedIn","en":"LinkedIn acquisition"}]},"NVDA":{"name":"NVIDIA","year":"1993","sector":{"uk":"Напівпровідники","en":"Semiconductors"},"history":{"uk":"Дженсен Хуанг, Кріс Малаховскі та Кертіс Прім заснували компанію графічних чипів. GeForce (1999) і CUDA (2006) відкрили шлях до обчислень для штучного інтелекту.","en":"Jensen Huang, Chris Malachowsky and Curtis Priem started a graphics-chip company. GeForce (1999) and CUDA (2006) paved the way for AI computing."},"source":"https://www.nvidia.com/","branches":{"uk":["GeForce","GPU для центрів обробки даних","CUDA та програмні платформи","Автомобільні обчислення"],"en":["GeForce","Data center GPUs","CUDA and software platforms","Automotive computing"]},"recognition":{"uk":"GeForce зробила бренд відомим геймерам. CUDA дала розробникам інструменти паралельних обчислень, а попит на навчання й запуск моделей ШІ перетворив GPU на ключовий продукт для дата-центрів.","en":"GeForce made the brand familiar to gamers. CUDA enabled parallel computing, and demand for AI training and inference made GPUs a central data center product."},"milestones":[{"year":"1993","uk":"Заснування NVIDIA","en":"NVIDIA founded"},{"year":"1999","uk":"GeForce 256","en":"GeForce 256"},{"year":"2006","uk":"CUDA","en":"CUDA"},{"year":"2012","uk":"GPU у прориві AlexNet","en":"GPUs power the AlexNet breakthrough"},{"year":"2018","uk":"GeForce RTX та трасування променів","en":"GeForce RTX and ray tracing"},{"year":"2020","uk":"Придбання Mellanox","en":"Mellanox acquisition"},{"year":"2022","uk":"H100","en":"H100"},{"year":"2024","uk":"Представлено архітектуру Blackwell","en":"Blackwell architecture announced"}]},"AMD":{"name":"AMD","year":"1969","sector":{"uk":"Напівпровідники","en":"Semiconductors"},"history":{"uk":"Джеррі Сандерс і колеги заснували виробника інтегральних схем. AMD розвинула процесори x86, придбала ATI у 2006 році та представила Ryzen у 2017 році.","en":"Jerry Sanders and colleagues founded an integrated-circuit maker. AMD expanded into x86 processors, acquired ATI in 2006 and introduced Ryzen in 2017."},"source":"https://www.amd.com/","branches":{"uk":["Ryzen","EPYC","Radeon","Вбудовані та адаптивні чипи"],"en":["Ryzen","EPYC","Radeon","Embedded and adaptive chips"]},"recognition":{"uk":"Athlon, а згодом Zen і Ryzen посилили конкуренцію у процесорах ПК. EPYC розширив присутність у серверах; Radeon і чипи для консолей зробили бренд помітним у геймінгу.","en":"Athlon and later Zen and Ryzen strengthened PC processor competition. EPYC expanded its server presence; Radeon and console chips made AMD prominent in gaming."},"milestones":[{"year":"1969","uk":"Заснування AMD","en":"AMD founded"},{"year":"2003","uk":"Opteron та архітектура AMD64","en":"Opteron and AMD64"},{"year":"2006","uk":"Придбання ATI","en":"ATI acquisition"},{"year":"2017","uk":"Ryzen та EPYC","en":"Ryzen and EPYC"},{"year":"2019","uk":"Zen 2 та EPYC Rome","en":"Zen 2 and EPYC Rome"},{"year":"2022","uk":"Придбання Xilinx","en":"Xilinx acquisition"}]},"INTC":{"name":"Intel","year":"1968","sector":{"uk":"Напівпровідники","en":"Semiconductors"},"history":{"uk":"Роберт Нойс і Гордон Мур заснували Intel для розробки напівпровідникової пам'яті. Intel 4004 (1971) започаткував напрям мікропроцесорів, який згодом розвинувся в архітектуру x86.","en":"Robert Noyce and Gordon Moore founded Intel to develop semiconductor memory. The 4004 (1971) began its microprocessor business, followed by x86."},"source":"https://www.intel.com/","branches":{"uk":["Процесори Core та Xeon","Виробництво напівпровідників","Платформні технології"],"en":["Core and Xeon processors","Semiconductor manufacturing","Platform technologies"]},"recognition":{"uk":"Мікропроцесори x86, поширення IBM-сумісних ПК і кампанія Intel Inside зробили Intel одним із найвідоміших імен у комп’ютерній індустрії.","en":"x86 processors, the spread of IBM-compatible PCs and the Intel Inside campaign made Intel one of computing's most recognizable brands."},"milestones":[{"year":"1968","uk":"Заснування Intel","en":"Intel founded"},{"year":"1971","uk":"Intel 4004","en":"Intel 4004"},{"year":"1978","uk":"8086","en":"8086"},{"year":"1985","uk":"Процесор Intel 386","en":"Intel 386 processor"},{"year":"1993","uk":"Pentium","en":"Pentium"},{"year":"2006","uk":"Intel Core 2","en":"Intel Core 2"}]},"AVGO":{"name":"Broadcom","year":"1961 / 1991 / 2016","sector":{"uk":"Напівпровідники та ПЗ","en":"Semiconductors and software"},"history":{"uk":"Один із витоків — напівпровідниковий підрозділ HP (1961); оригінальну Broadcom засновано у 1991 році. Avago придбала Broadcom у 2016 році, сформувавши сучасну групу.","en":"One lineage traces to HP's semiconductor operations (1961); the original Broadcom was founded in 1991. Avago acquired Broadcom in 2016, forming the modern group."},"source":"https://investors.broadcom.com/","branches":{"uk":["Мережеві чипи","Компоненти для підключення","Інфраструктурне ПЗ"],"en":["Networking chips","Connectivity components","Infrastructure software"]},"recognition":{"uk":"Broadcom відома насамперед постачальникам обладнання та дата-центрам. Злиття й придбання розширили портфель від напівпровідників до корпоративного ПЗ, зокрема VMware.","en":"Broadcom is best known to equipment makers and data centers. Acquisitions expanded its portfolio from semiconductors into enterprise software, including VMware."},"milestones":[{"year":"1961","uk":"Витоки в напівпровідниковому підрозділі HP","en":"Roots in HP's semiconductor division"},{"year":"1991","uk":"Засновано оригінальну Broadcom","en":"Original Broadcom founded"},{"year":"2005","uk":"Створення Avago Technologies","en":"Avago Technologies established"},{"year":"2016","uk":"Злиття Avago і Broadcom","en":"Avago and Broadcom combination"},{"year":"2018","uk":"Придбання CA Technologies","en":"CA Technologies acquisition"},{"year":"2023","uk":"Придбання VMware","en":"VMware acquisition"}]},"IBM":{"name":"IBM","year":"1911","sector":{"uk":"ІТ та обчислення","en":"IT and computing"},"history":{"uk":"Компанія виникла як Computing-Tabulating-Recording Company, що об'єднала виробників облікових машин. У 1924 році стала IBM, згодом розвинула мейнфрейми, персональні комп'ютери й корпоративні ІТ.","en":"The Computing-Tabulating-Recording Company combined business-machine makers. Renamed IBM in 1924, it developed mainframes, personal computers and enterprise IT."},"source":"https://www.ibm.com/","branches":{"uk":["Корпоративне ПЗ","Гібридна хмара","Консалтинг","Мейнфрейми"],"en":["Enterprise software","Hybrid cloud","Consulting","Mainframes"]},"recognition":{"uk":"System/360 і мейнфрейми закріпили IBM у великих організаціях. IBM PC вплинув на стандарти персональних комп’ютерів; згодом компанія зосередилася на корпоративних технологіях.","en":"System/360 and mainframes established IBM in large organizations. The IBM PC shaped personal computing standards; the company later focused on enterprise technology."},"milestones":[{"year":"1911","uk":"Створення Computing-Tabulating-Recording Company","en":"Computing-Tabulating-Recording Company formed"},{"year":"1924","uk":"Назва International Business Machines","en":"International Business Machines name adopted"},{"year":"1964","uk":"System/360","en":"System/360"},{"year":"1981","uk":"IBM PC","en":"IBM PC"},{"year":"2011","uk":"Watson перемагає в Jeopardy!","en":"Watson wins Jeopardy!"},{"year":"2019","uk":"Red Hat","en":"Red Hat"}]},"ORCL":{"name":"Oracle","year":"1977","sector":{"uk":"Бази даних та ПЗ","en":"Databases and software"},"history":{"uk":"Ларрі Еллісон, Боб Майнер і Ед Оутс створили Software Development Laboratories. Реляційні бази даних стали основою бізнесу Oracle, який згодом розширився до корпоративного ПЗ і хмар.","en":"Larry Ellison, Bob Miner and Ed Oates founded Software Development Laboratories. Relational databases became the foundation for Oracle's enterprise software and cloud business."},"source":"https://www.oracle.com/","branches":{"uk":["Бази даних","Oracle Cloud","ERP та корпоративні застосунки"],"en":["Databases","Oracle Cloud","ERP and enterprise applications"]},"recognition":{"uk":"Реляційна база даних Oracle стала основою впізнаваності в корпоративному секторі. Бізнес розширився завдяки ERP, придбанню Sun та хмарній інфраструктурі.","en":"Oracle's relational database established its enterprise reputation. ERP, Sun's acquisition and cloud infrastructure broadened the business."},"milestones":[{"year":"1977","uk":"Заснування Software Development Laboratories","en":"Software Development Laboratories founded"},{"year":"1979","uk":"Oracle Version 2","en":"Oracle Version 2"},{"year":"1986","uk":"Вихід на біржу","en":"IPO"},{"year":"2005","uk":"Придбання PeopleSoft","en":"PeopleSoft acquisition"},{"year":"2010","uk":"Придбання Sun","en":"Sun acquisition"},{"year":"2022","uk":"Придбання Cerner","en":"Cerner acquisition"}]},"META":{"name":"Meta","year":"2004","sector":{"uk":"Соціальні мережі","en":"Social platforms"},"history":{"uk":"Facebook почався як студентська соціальна мережа Гарварду. Компанія придбала Instagram (2012) і WhatsApp (2014), а у 2021 році змінила назву на Meta.","en":"Facebook began as a Harvard student social network. It acquired Instagram (2012) and WhatsApp (2014) and renamed itself Meta in 2021."},"source":"https://about.meta.com/","branches":{"uk":["Facebook","Instagram","WhatsApp","Reality Labs"],"en":["Facebook","Instagram","WhatsApp","Reality Labs"]},"recognition":{"uk":"Facebook виріс завдяки мережевому ефекту соціальних зв’язків. Instagram та WhatsApp розширили аудиторію, а рекламна платформа стала ключовою бізнес-моделлю.","en":"Facebook grew through social network effects. Instagram and WhatsApp expanded its audience, and advertising became a core business model."},"milestones":[{"year":"2004","uk":"Facebook","en":"Facebook"},{"year":"2006","uk":"Facebook відкривається широкій аудиторії","en":"Facebook opens to wider public"},{"year":"2012","uk":"Instagram","en":"Instagram"},{"year":"2012","uk":"IPO Facebook","en":"Facebook IPO"},{"year":"2014","uk":"WhatsApp","en":"WhatsApp"},{"year":"2021","uk":"Назва Meta","en":"Meta name"},{"year":"2023","uk":"Запуск Threads","en":"Threads launch"}]},"GOOGL":{"name":"Alphabet","year":"1998 / 2015","sector":{"uk":"Інтернет та технології","en":"Internet and technology"},"history":{"uk":"Ларрі Пейдж і Сергій Брін створили Google на основі пошукового проєкту. У 2015 році Alphabet стала материнською компанією Google та інших бізнесів.","en":"Larry Page and Sergey Brin created Google from a search project. In 2015 Alphabet became the parent company of Google and other businesses."},"source":"https://abc.xyz/","branches":{"uk":["Google Search і реклама","YouTube","Android","Google Cloud"],"en":["Google Search and advertising","YouTube","Android","Google Cloud"]},"recognition":{"uk":"PageRank допоміг Google вирізнитися серед пошуковиків. Пошукова реклама, YouTube і Android створили масштабну екосистему; Alphabet стала холдингом для різних напрямів.","en":"PageRank helped Google stand out among search engines. Search advertising, YouTube and Android built a large ecosystem; Alphabet became the holding company for different businesses."},"milestones":[{"year":"1998","uk":"Google","en":"Google"},{"year":"2004","uk":"IPO Google та запуск Gmail","en":"Google IPO and Gmail launch"},{"year":"2005","uk":"Google Maps","en":"Google Maps"},{"year":"2006","uk":"Придбання YouTube","en":"YouTube acquisition"},{"year":"2008","uk":"Android і Chrome","en":"Android and Chrome"},{"year":"2015","uk":"Alphabet","en":"Alphabet"},{"year":"2023","uk":"Представлено Gemini","en":"Gemini introduced"}]},"AMZN":{"name":"Amazon","year":"1994","sector":{"uk":"Електронна комерція та хмари","en":"E-commerce and cloud"},"history":{"uk":"Джефф Безос заснував компанію, яка почала з онлайн-продажу книжок у 1995 році. Згодом вона розширила асортимент, логістику та запустила AWS у 2006 році.","en":"Jeff Bezos founded the company, which began selling books online in 1995. It expanded into retail, logistics and launched AWS in 2006."},"source":"https://www.aboutamazon.com/","branches":{"uk":["Онлайн-торгівля","AWS","Prime","Логістика та реклама"],"en":["Online retail","AWS","Prime","Logistics and advertising"]},"recognition":{"uk":"Amazon почала з книжок, але стала універсальним маркетплейсом. Prime і логістика зміцнили клієнтську пропозицію, а AWS зробила компанію відомою у хмарній інфраструктурі.","en":"Amazon began with books and became a broad marketplace. Prime and logistics strengthened its customer proposition, while AWS established its cloud infrastructure business."},"milestones":[{"year":"1994","uk":"Заснування Amazon","en":"Amazon founded"},{"year":"1995","uk":"Онлайн-книгарня","en":"Online bookstore"},{"year":"1997","uk":"Вихід на біржу","en":"IPO"},{"year":"2005","uk":"Prime","en":"Prime"},{"year":"2006","uk":"AWS","en":"AWS"},{"year":"2007","uk":"Kindle","en":"Kindle"},{"year":"2017","uk":"Придбання Whole Foods Market","en":"Whole Foods Market acquisition"}]},"NFLX":{"name":"Netflix","year":"1997","sector":{"uk":"Стримінг та медіа","en":"Streaming and media"},"history":{"uk":"Рід Гастінгс і Марк Рендольф створили сервіс прокату DVD поштою. У 2007 році Netflix почав потокове мовлення, а згодом — виробництво власного контенту.","en":"Reed Hastings and Marc Randolph created a DVD-by-mail rental service. Netflix introduced streaming in 2007 and later began producing original content."},"source":"https://about.netflix.com/","branches":{"uk":["Стримінг","Власні фільми й серіали","Ліцензований контент"],"en":["Streaming","Original films and series","Licensed content"]},"recognition":{"uk":"Перехід від DVD поштою до стримінгу змінив модель бізнесу. Власні серіали, зокрема House of Cards, і глобальні хіти на кшталт Squid Game посилили впізнаваність.","en":"The transition from DVD-by-mail to streaming transformed the business. Original series such as House of Cards and global hits such as Squid Game strengthened recognition."},"milestones":[{"year":"1997","uk":"Заснування Netflix","en":"Netflix founded"},{"year":"1998","uk":"Прокат DVD поштою","en":"DVD-by-mail service"},{"year":"2002","uk":"IPO","en":"IPO"},{"year":"2007","uk":"Запуск стримінгу","en":"Streaming launch"},{"year":"2013","uk":"House of Cards","en":"House of Cards"},{"year":"2016","uk":"Масштабне міжнародне розширення","en":"Major international expansion"},{"year":"2021","uk":"Squid Game","en":"Squid Game"}]},"UBER":{"name":"Uber","year":"2009","sector":{"uk":"Транспортні платформи","en":"Transport platforms"},"history":{"uk":"Гарретт Кемп і Тревіс Каланік створили UberCab для замовлення поїздок через смартфон. Згодом платформа розширилася до доставки та інших транспортних послуг.","en":"Garrett Camp and Travis Kalanick founded UberCab for smartphone-based ride booking. It later expanded into delivery and other mobility services."},"source":"https://www.uber.com/","branches":{"uk":["Поїздки","Uber Eats","Вантажна логістика"],"en":["Ride-hailing","Uber Eats","Freight logistics"]},"recognition":{"uk":"Замовлення поїздки через смартфон та платформа, що з’єднує водіїв із пасажирами, зробили Uber впізнаваним. Доставка їжі розширила використання застосунку.","en":"Smartphone ride booking and a platform connecting drivers and riders made Uber recognizable. Food delivery broadened the app's use."},"milestones":[{"year":"2009","uk":"Заснування UberCab","en":"UberCab founded"},{"year":"2010","uk":"Перші поїздки","en":"First rides"},{"year":"2014","uk":"Початок сервісу доставки UberFRESH","en":"UberFRESH delivery service begins"},{"year":"2015","uk":"Запуск Uber Eats як окремого застосунку","en":"Uber Eats standalone app launches"},{"year":"2019","uk":"IPO","en":"IPO"}]},"ADBE":{"name":"Adobe","year":"1982","sector":{"uk":"Творче ПЗ","en":"Creative software"},"history":{"uk":"Джон Ворнок і Чарльз Гешке заснували Adobe. Початковий продукт PostScript допоміг розвитку цифрового друку, пізніше з'явилися Photoshop, PDF та Creative Cloud.","en":"John Warnock and Charles Geschke founded Adobe. PostScript helped establish digital publishing, followed by Photoshop, PDF and Creative Cloud."},"source":"https://www.adobe.com/","branches":{"uk":["Photoshop та Illustrator","Creative Cloud","Acrobat і PDF","Маркетингові технології"],"en":["Photoshop and Illustrator","Creative Cloud","Acrobat and PDF","Marketing technology"]},"recognition":{"uk":"PostScript та PDF вплинули на цифрові документи й друк. Photoshop став широко відомим редактором зображень, а Creative Cloud об’єднала професійні інструменти за підпискою.","en":"PostScript and PDF influenced digital publishing and documents. Photoshop became a widely known image editor, while Creative Cloud bundled professional tools into a subscription."},"milestones":[{"year":"1982","uk":"Заснування Adobe","en":"Adobe founded"},{"year":"1985","uk":"PostScript","en":"PostScript"},{"year":"1990","uk":"Photoshop","en":"Photoshop"},{"year":"1993","uk":"PDF","en":"PDF"},{"year":"2005","uk":"Придбання Macromedia","en":"Macromedia acquisition"},{"year":"2012","uk":"Запуск Creative Cloud","en":"Creative Cloud launch"}]},"CRM":{"name":"Salesforce","year":"1999","sector":{"uk":"Корпоративне хмарне ПЗ","en":"Enterprise cloud software"},"history":{"uk":"Марк Беніофф і співзасновники започаткували CRM-сервіс через інтернет. Модель ПЗ за підпискою стала основою платформи продажів, маркетингу та обслуговування.","en":"Marc Benioff and co-founders launched an online CRM service. Subscription software became the basis for its sales, marketing and service platform."},"source":"https://www.salesforce.com/","branches":{"uk":["Sales Cloud","Service Cloud","Slack","Платформа даних та інтеграцій"],"en":["Sales Cloud","Service Cloud","Slack","Data and integration platforms"]},"recognition":{"uk":"Salesforce популяризувала CRM через браузер і модель підписки замість локального встановлення. Розширення платформи та придбання Slack і Tableau зміцнили корпоративну екосистему.","en":"Salesforce popularized browser-based subscription CRM instead of local installations. Platform expansion and acquisitions of Slack and Tableau strengthened its enterprise ecosystem."},"milestones":[{"year":"1999","uk":"Заснування Salesforce","en":"Salesforce founded"},{"year":"2004","uk":"IPO","en":"IPO"},{"year":"2005","uk":"Запуск AppExchange","en":"AppExchange launch"},{"year":"2018","uk":"Придбання MuleSoft","en":"MuleSoft acquisition"},{"year":"2019","uk":"Tableau","en":"Tableau"},{"year":"2021","uk":"Slack","en":"Slack"}]},"PLTR":{"name":"Palantir","year":"2003","sector":{"uk":"Аналітика даних","en":"Data analytics"},"history":{"uk":"Компанія починала з інструментів інтеграції та аналізу даних для державних установ. Згодом платформи Gotham і Foundry розширили її роботу з великими організаціями.","en":"The company began building data integration and analysis tools for government agencies. Gotham and Foundry later expanded its work with large organizations."},"source":"https://www.palantir.com/","branches":{"uk":["Gotham","Foundry","Apollo","AIP"],"en":["Gotham","Foundry","Apollo","AIP"]},"recognition":{"uk":"Palantir стала відомою завдяки аналітиці великих наборів даних для державних структур. Foundry розширила застосування у бізнесі, а AIP привернула увагу до інтеграції ШІ в робочі процеси.","en":"Palantir became known for large-scale data analytics in government. Foundry expanded its commercial uses, while AIP drew attention to AI integration into workflows."},"milestones":[{"year":"2003","uk":"Заснування Palantir","en":"Palantir founded"},{"year":"2020","uk":"Прямий лістинг","en":"Direct listing"},{"year":"2023","uk":"AIP","en":"AIP"},{"year":"2024","uk":"Включення до S&P 500","en":"Added to S&P 500"}]},"ASML":{"name":"ASML","year":"1984","sector":{"uk":"Літографія","en":"Lithography"},"history":{"uk":"Створена як спільне підприємство Philips і ASM International для виробництва літографічних систем. Розвиток DUV та EUV зробив її важливим постачальником обладнання для чипів.","en":"Founded as a joint venture between Philips and ASM International to make lithography systems. DUV and EUV technologies made it a key chip-equipment supplier."},"source":"https://www.asml.com/en/company/about-asml/history","branches":{"uk":["DUV-літографія","EUV-літографія","High-NA EUV","Обслуговування обладнання"],"en":["DUV lithography","EUV lithography","High-NA EUV","Equipment services"]},"recognition":{"uk":"Унікальна складність EUV-літографії та тривала співпраця з виробниками чипів зробили ASML критично важливим постачальником передових систем виробництва напівпровідників.","en":"The complexity of EUV lithography and long-term collaboration with chipmakers made ASML a critical supplier of advanced semiconductor manufacturing systems."},"milestones":[{"year":"1984","uk":"Заснування ASML","en":"ASML founded"},{"year":"1995","uk":"IPO ASML","en":"ASML IPO"},{"year":"2001","uk":"Перша система TWINSCAN","en":"First TWINSCAN system"},{"year":"2010","uk":"Перший прототип EUV NXE","en":"First NXE EUV prototype"},{"year":"2023","uk":"Перша поставка High-NA EUV","en":"First High-NA EUV shipment"}]},"TSM":{"name":"TSMC","year":"1987","sector":{"uk":"Виробництво чипів","en":"Chip manufacturing"},"history":{"uk":"Морріс Чанг заснував TSMC на Тайвані з моделлю контрактного виробництва чипів. Вона дала змогу компаніям проєктувати мікросхеми без власних фабрик.","en":"Morris Chang founded TSMC in Taiwan around the dedicated foundry model. It enabled chip designers to manufacture without owning factories."},"source":"https://www.tsmc.com/","branches":{"uk":["Контрактне виробництво чипів","Передові техпроцеси","Упаковка напівпровідників"],"en":["Contract chip manufacturing","Advanced process nodes","Semiconductor packaging"]},"recognition":{"uk":"TSMC зробила спеціалізоване контрактне виробництво основою бізнесу, дозволяючи розробникам чипів працювати без власних фабрик. Передові техпроцеси й масштаб стали джерелом її галузевої впізнаваності.","en":"TSMC built its business around dedicated foundry manufacturing, enabling chip designers to operate without their own fabs. Advanced process nodes and scale drove industry recognition."},"milestones":[{"year":"1987","uk":"Запуск спеціалізованої foundry-моделі","en":"Dedicated foundry model launches"},{"year":"1994","uk":"Лістинг на Тайванській фондовій біржі","en":"Taiwan Stock Exchange listing"},{"year":"1997","uk":"Лістинг ADR на NYSE","en":"NYSE ADR listing"},{"year":"2018","uk":"Серійне виробництво 7-нм чипів","en":"7nm volume production"},{"year":"2020","uk":"Масове виробництво 5 нм","en":"5nm volume production"},{"year":"2022","uk":"Серійне виробництво 3-нм чипів","en":"3nm volume production"}]},"QCOM":{"name":"Qualcomm","year":"1985","sector":{"uk":"Бездротові технології","en":"Wireless technology"},"history":{"uk":"Компанію заснували фахівці зі зв'язку, зокрема Ірвін Джейкобс. Розробки CDMA, а пізніше Snapdragon і мобільні модеми стали ключовими напрямами.","en":"Communications specialists including Irwin Jacobs founded Qualcomm. CDMA, followed by Snapdragon and mobile modems, became central to its business."},"source":"https://www.qualcomm.com/","branches":{"uk":["Snapdragon","Мобільні модеми","Патентне ліцензування","Автомобільні платформи"],"en":["Snapdragon","Mobile modems","Patent licensing","Automotive platforms"]},"recognition":{"uk":"Розробка CDMA та технологій мобільного зв’язку дала Qualcomm сильну позицію в галузі. Snapdragon зробив назву впізнаваною серед покупців смартфонів.","en":"CDMA and mobile communications technology gave Qualcomm a strong industry position. Snapdragon made the name familiar to smartphone buyers."},"milestones":[{"year":"1985","uk":"Заснування Qualcomm","en":"Qualcomm founded"},{"year":"1989","uk":"Демонстрація CDMA для мобільного зв'язку","en":"CDMA mobile communications demonstration"},{"year":"1991","uk":"IPO","en":"IPO"},{"year":"2007","uk":"Перший Snapdragon","en":"First Snapdragon"},{"year":"2019","uk":"Комерційні платформи 5G","en":"Commercial 5G platforms"}]},"MU":{"name":"Micron","year":"1978","sector":{"uk":"Напівпровідникова пам'ять","en":"Semiconductor memory"},"history":{"uk":"Компанія виникла в Бойсі як бізнес із проєктування напівпровідників. Виробництво DRAM, а пізніше NAND, сформувало її основну спеціалізацію.","en":"Founded in Boise as a semiconductor design business, Micron grew into DRAM and later NAND memory manufacturing."},"source":"https://www.micron.com/","branches":{"uk":["DRAM","NAND","HBM та пам’ять для дата-центрів"],"en":["DRAM","NAND","HBM and data center memory"]},"recognition":{"uk":"Micron стала відомою у виробництві пам’яті для ПК, мобільних пристроїв і серверів. Зростання потреб у високошвидкісній пам’яті посилило увагу до HBM.","en":"Micron became known for memory used in PCs, mobile devices and servers. Growing demand for high-bandwidth memory increased attention to HBM."},"milestones":[{"year":"1978","uk":"Заснування Micron","en":"Micron founded"},{"year":"1984","uk":"IPO Micron","en":"Micron IPO"},{"year":"1998","uk":"Придбання бізнесу пам'яті Texas Instruments","en":"Texas Instruments memory business acquisition"},{"year":"2013","uk":"Придбання Elpida","en":"Elpida acquisition"}]},"TSLA":{"name":"Tesla","year":"2003","sector":{"uk":"Електромобілі та енергетика","en":"Electric vehicles and energy"},"history":{"uk":"Мартін Ебергард і Марк Тарпеннінг започаткували Tesla Motors; Ілон Маск приєднався як інвестор у 2004 році. Roadster (2008) і Model S (2012) стали ключовими етапами.","en":"Martin Eberhard and Marc Tarpenning started Tesla Motors; Elon Musk joined as an investor in 2004. The Roadster (2008) and Model S (2012) were major milestones."},"source":"https://www.tesla.com/","branches":{"uk":["Електромобілі","Акумуляторні системи","Зарядна мережа","Програмні функції автомобілів"],"en":["Electric vehicles","Battery storage","Charging network","Vehicle software"]},"recognition":{"uk":"Roadster показав можливості спортивного електромобіля, Model S зміцнив преміальний імідж, а Model 3 і Model Y розширили масовий ринок. Supercharger та оновлення ПЗ стали помітними рисами бренду.","en":"Roadster demonstrated electric sports car performance, Model S reinforced the premium image, and Model 3 and Model Y broadened the mass market. Supercharger and software updates became recognizable features."},"milestones":[{"year":"2003","uk":"Заснування Tesla Motors","en":"Tesla Motors founded"},{"year":"2008","uk":"Roadster","en":"Roadster"},{"year":"2010","uk":"IPO","en":"IPO"},{"year":"2012","uk":"Model S","en":"Model S"},{"year":"2015","uk":"Model X","en":"Model X"},{"year":"2017","uk":"Model 3","en":"Model 3"},{"year":"2020","uk":"Model Y","en":"Model Y"},{"year":"2023","uk":"Перші поставки Cybertruck","en":"First Cybertruck deliveries"}]},"RACE":{"name":"Ferrari","year":"1947","sector":{"uk":"Автомобілі","en":"Automotive"},"history":{"uk":"Енцо Феррарі створив гоночну команду Scuderia Ferrari у 1929 році. У 1947 році з'явився перший автомобіль марки Ferrari — 125 S; дорожні спорткари розвинулися поряд із автоспортом.","en":"Enzo Ferrari founded Scuderia Ferrari in 1929. The first Ferrari-branded car, the 125 S, appeared in 1947; road sports cars grew alongside racing."},"source":"https://www.ferrari.com/","branches":{"uk":["Спортивні автомобілі","Автоспорт","Ліцензування бренду"],"en":["Sports cars","Motorsport","Brand licensing"]},"recognition":{"uk":"Ferrari поєднала гоночну спадщину, інженерію й обмежене виробництво дорожніх автомобілів. Формула-1 та культові моделі стали джерелом глобальної впізнаваності.","en":"Ferrari combined racing heritage, engineering and limited road-car production. Formula 1 and iconic models drove global recognition."},"milestones":[{"year":"1929","uk":"Створення Scuderia Ferrari","en":"Scuderia Ferrari founded"},{"year":"1947","uk":"125 S","en":"125 S"},{"year":"1950","uk":"Дебют у Формулі-1","en":"Formula 1 debut"},{"year":"1969","uk":"Fiat входить до капіталу Ferrari","en":"Fiat acquires a stake in Ferrari"},{"year":"2015","uk":"IPO","en":"IPO"},{"year":"2016","uk":"Відокремлення від FCA","en":"Separation from FCA"}]},"JPM":{"name":"JPMorgan Chase","year":"1799 / 2000","sector":{"uk":"Банківська справа","en":"Banking"},"history":{"uk":"Витоки групи сягають Manhattan Company (1799). Сучасний JPMorgan Chase сформувався у 2000 році внаслідок об'єднання Chase Manhattan та J.P. Morgan.","en":"Its roots extend to the Manhattan Company (1799). The modern JPMorgan Chase formed in 2000 through the merger of Chase Manhattan and J.P. Morgan."},"source":"https://www.jpmorganchase.com/","branches":{"uk":["Споживчий банкінг Chase","Інвестиційний банкінг","Управління активами","Платежі"],"en":["Chase consumer banking","Investment banking","Asset management","Payments"]},"recognition":{"uk":"Масштаб роздрібної мережі Chase та корпоративні фінансові послуги J.P. Morgan сформували дві впізнавані частини групи. Злиття розширили її можливості.","en":"Chase's retail network and J.P. Morgan's corporate finance services formed two recognizable parts of the group. Mergers broadened its capabilities."},"milestones":[{"year":"1799","uk":"Витоки в Manhattan Company","en":"Roots in the Manhattan Company"},{"year":"2000","uk":"Злиття Chase та J.P. Morgan","en":"Chase and J.P. Morgan merger"},{"year":"2004","uk":"Bank One","en":"Bank One"},{"year":"2008","uk":"Придбання Bear Stearns та банківських активів Washington Mutual","en":"Bear Stearns and Washington Mutual banking assets acquired"},{"year":"2023","uk":"Придбання більшості активів First Republic","en":"Acquisition of most First Republic assets"}]},"BAC":{"name":"Bank of America","year":"1904 / 1998","sector":{"uk":"Банківська справа","en":"Banking"},"history":{"uk":"Амадео Джанніні заснував Bank of Italy у 1904 році для обслуговування широкого кола клієнтів. Сучасна група сформувалася після злиття NationsBank і BankAmerica у 1998 році.","en":"Amadeo Giannini founded the Bank of Italy in 1904 to serve a broad customer base. The modern group formed through the NationsBank–BankAmerica merger in 1998."},"source":"https://about.bankofamerica.com/","branches":{"uk":["Роздрібний банкінг","Merrill","Корпоративний банкінг","Управління капіталом"],"en":["Retail banking","Merrill","Corporate banking","Wealth management"]},"recognition":{"uk":"Банк виріс завдяки розширенню доступу до роздрібних фінансових послуг і злиттям. Merrill Lynch зміцнила інвестиційний та консультаційний напрями.","en":"The bank grew through wider access to retail financial services and mergers. Merrill Lynch strengthened investment and advisory operations."},"milestones":[{"year":"1904","uk":"Відкриття Bank of Italy","en":"Bank of Italy opens"},{"year":"1958","uk":"Запуск BankAmericard","en":"BankAmericard launch"},{"year":"1998","uk":"Злиття з NationsBank","en":"NationsBank merger"},{"year":"2008","uk":"Придбання Countrywide","en":"Countrywide acquisition"},{"year":"2009","uk":"Придбання Merrill Lynch","en":"Merrill Lynch acquisition"}]},"V":{"name":"Visa","year":"1958 / 2007","sector":{"uk":"Платіжні системи","en":"Payments"},"history":{"uk":"Мережа бере початок із програми BankAmericard 1958 року. Назва Visa з'явилася у 1976 році, Visa Inc. створено у 2007 році.","en":"The network originated with BankAmericard in 1958. The Visa name appeared in 1976 and Visa Inc. was formed in 2007."},"source":"https://corporate.visa.com/en/about-visa.html","branches":{"uk":["Платіжна мережа","Обробка транзакцій","Цифрові платежі"],"en":["Payment network","Transaction processing","Digital payments"]},"recognition":{"uk":"Visa стала впізнаваною завдяки міжнародному прийманню карток і мережевому ефекту між банками, продавцями та покупцями. Вона керує платіжною мережею, а не видає більшість карток сама.","en":"Visa gained recognition through global card acceptance and network effects across banks, merchants and consumers. It operates a payment network rather than issuing most cards itself."},"milestones":[{"year":"1958","uk":"BankAmericard","en":"BankAmericard"},{"year":"1970","uk":"Створення National BankAmericard Inc.","en":"National BankAmericard Inc. formed"},{"year":"1976","uk":"Назва Visa","en":"Visa name"},{"year":"2008","uk":"IPO","en":"IPO"},{"year":"2016","uk":"Придбання Visa Europe","en":"Visa Europe acquisition"}]},"MA":{"name":"Mastercard","year":"1966","sector":{"uk":"Платіжні системи","en":"Payments"},"history":{"uk":"Група банків створила Interbank Card Association для спільної платіжної мережі. У 1979 році бренд отримав назву MasterCard та продовжив міжнародне розширення.","en":"A group of banks formed the Interbank Card Association to operate a shared payment network. It adopted the MasterCard name in 1979 and expanded internationally."},"source":"https://www.mastercard.com/brandcenter/us/en/brand-history.html","branches":{"uk":["Карткова мережа","Цифрові платежі","Сервіси безпеки й аналітики"],"en":["Card network","Digital payments","Security and analytics services"]},"recognition":{"uk":"Міжбанківська платіжна мережа й глобальне приймання карток зробили Mastercard впізнаваною. Рекламна кампанія Priceless також стала важливою частиною бренду.","en":"The interbank payment network and global card acceptance made Mastercard recognizable. The Priceless advertising campaign also became a key part of the brand."},"milestones":[{"year":"1966","uk":"Заснування Interbank Card Association","en":"Interbank Card Association founded"},{"year":"1969","uk":"Назва Master Charge","en":"Master Charge name introduced"},{"year":"1979","uk":"Назва Mastercard","en":"Mastercard name"},{"year":"1997","uk":"Priceless","en":"Priceless"},{"year":"2006","uk":"IPO","en":"IPO"},{"year":"2016","uk":"Оновлення фірмового знака","en":"Brand mark redesign"}]},"BRK-B":{"name":"Berkshire Hathaway","year":"1839 / 1955 / 1965","sector":{"uk":"Інвестиційний холдинг","en":"Conglomerate"},"history":{"uk":"Витоки сягають текстильних підприємств XIX століття; Berkshire Hathaway утворилася після злиття у 1955 році. У 1965 році Воррен Баффетт отримав контроль і поступово перетворив її на інвестиційний холдинг.","en":"Its origins lie in 19th-century textile mills; Berkshire Hathaway formed through a merger in 1955. Warren Buffett took control in 1965 and transformed it into a conglomerate."},"source":"https://www.berkshirehathaway.com/","branches":{"uk":["Страхування GEICO","Залізниця BNSF","Енергетика","Інвестиції та інші бізнеси"],"en":["GEICO insurance","BNSF railway","Energy","Investments and other businesses"]},"recognition":{"uk":"Воррен Баффетт перетворив текстильне підприємство на диверсифікований холдинг. Довгострокове інвестування й використання страхового капіталу зробили Berkshire відомою серед інвесторів.","en":"Warren Buffett transformed a textile company into a diversified holding company. Long-term investing and insurance float made Berkshire well known among investors."},"milestones":[{"year":"1839","uk":"Витоки текстильного підприємства Valley Falls Company","en":"Textile roots in Valley Falls Company"},{"year":"1955","uk":"Об'єднання Berkshire та Hathaway","en":"Berkshire and Hathaway merger"},{"year":"1965","uk":"Контроль Баффетта","en":"Buffett takes control"},{"year":"1967","uk":"Придбання National Indemnity","en":"National Indemnity acquisition"},{"year":"1996","uk":"Повне придбання GEICO","en":"Full acquisition of GEICO"},{"year":"2010","uk":"Придбання BNSF","en":"BNSF acquisition"}]},"XOM":{"name":"ExxonMobil","year":"1870 / 1999","sector":{"uk":"Нафта та газ","en":"Oil and gas"},"history":{"uk":"Коріння компаній-попередників — Standard Oil, заснована у 1870 році. Exxon і Mobil об'єдналися у 1999 році, утворивши сучасну енергетичну групу.","en":"Its predecessor companies trace their roots to Standard Oil, founded in 1870. Exxon and Mobil merged in 1999 to create the modern energy group."},"source":"https://corporate.exxonmobil.com/","branches":{"uk":["Видобуток нафти й газу","Переробка та паливо","Хімічна продукція"],"en":["Oil and gas production","Refining and fuels","Chemical products"]},"recognition":{"uk":"Спадщина Standard Oil, масштабна інтеграція видобутку й переробки та бренди Exxon, Mobil і Esso сформували міжнародну впізнаваність.","en":"Standard Oil heritage, integrated production and refining, and the Exxon, Mobil and Esso brands created international recognition."},"milestones":[{"year":"1870","uk":"Заснування Standard Oil","en":"Standard Oil founded"},{"year":"1911","uk":"Поділ Standard Oil","en":"Standard Oil breakup"},{"year":"1972","uk":"Назва Exxon у США","en":"Exxon name adopted in the US"},{"year":"1999","uk":"Злиття Exxon та Mobil","en":"Exxon and Mobil merger"},{"year":"2024","uk":"Придбання Pioneer Natural Resources","en":"Pioneer Natural Resources acquisition"}]},"CVX":{"name":"Chevron","year":"1879","sector":{"uk":"Нафта та газ","en":"Oil and gas"},"history":{"uk":"Витоки — Pacific Coast Oil Company, заснована у Каліфорнії у 1879 році. Бізнес зростав через видобуток, переробку та злиття, зокрема з Texaco у 2001 році.","en":"Its roots lie in Pacific Coast Oil Company, founded in California in 1879. The business grew through production, refining and mergers, including Texaco in 2001."},"source":"https://www.chevron.com/","branches":{"uk":["Видобуток","Переробка","Паливні бренди","Хімічні продукти"],"en":["Production","Refining","Fuel brands","Chemical products"]},"recognition":{"uk":"Chevron виросла з каліфорнійського нафтового бізнесу до міжнародної інтегрованої групи. Бренди Chevron і Texaco та масштабні проєкти видобутку визначають її впізнаваність.","en":"Chevron grew from a California oil business into an international integrated group. Chevron and Texaco brands and large production projects define its recognition."},"milestones":[{"year":"1879","uk":"Заснування Pacific Coast Oil Company","en":"Pacific Coast Oil Company founded"},{"year":"1984","uk":"Придбання Gulf Oil","en":"Gulf Oil acquisition"},{"year":"2001","uk":"Злиття з Texaco","en":"Texaco merger"},{"year":"2005","uk":"Придбання Unocal","en":"Unocal acquisition"},{"year":"2020","uk":"Придбання Noble Energy","en":"Noble Energy acquisition"}]},"SHEL":{"name":"Shell","year":"1907","sector":{"uk":"Енергетика","en":"Energy"},"history":{"uk":"Royal Dutch Petroleum і Shell Transport and Trading об'єднали діяльність у 1907 році. Група розвивала видобуток нафти, транспортування, переробку та газовий бізнес.","en":"Royal Dutch Petroleum and Shell Transport and Trading combined operations in 1907. The group expanded into oil production, transport, refining and gas."},"source":"https://www.shell.com/","branches":{"uk":["Нафта й газ","LNG","Переробка та роздрібне паливо"],"en":["Oil and gas","LNG","Refining and retail fuels"]},"recognition":{"uk":"Міжнародна мережа АЗС, емблема мушлі та масштабний бізнес скрапленого природного газу зробили Shell відомою як споживачам, так і промисловим клієнтам.","en":"An international fuel station network, the shell emblem and a major LNG business made Shell recognizable to consumers and industrial customers."},"milestones":[{"year":"1897","uk":"Створення Shell Transport and Trading","en":"Shell Transport and Trading founded"},{"year":"1907","uk":"Об’єднання Royal Dutch і Shell","en":"Royal Dutch and Shell combination"},{"year":"2005","uk":"Єдина материнська компанія Royal Dutch Shell","en":"Unified Royal Dutch Shell parent company"},{"year":"2016","uk":"Придбання BG Group","en":"BG Group acquisition"},{"year":"2022","uk":"Назва Shell plc","en":"Shell plc name adopted"}]},"JNJ":{"name":"Johnson & Johnson","year":"1886","sector":{"uk":"Медицина","en":"Healthcare"},"history":{"uk":"Брати Джонсон заснували компанію з виробництва медичних матеріалів для хірургії. Згодом вона розвинула фармацевтичний бізнес та медичні технології.","en":"The Johnson brothers founded a surgical-supplies company. It later expanded into pharmaceuticals and medical technology."},"source":"https://www.jnj.com/","branches":{"uk":["Інноваційні ліки","Медичні технології","Хірургічні вироби"],"en":["Innovative medicines","Medical technology","Surgical products"]},"recognition":{"uk":"Компанія здобула впізнаваність завдяки медичним матеріалам і споживчим брендам минулих десятиліть. Після відокремлення Kenvue основою залишилися ліки та медичні технології.","en":"Medical supplies and historical consumer brands built recognition. Following the Kenvue separation, medicines and medical technology became its core focus."},"milestones":[{"year":"1886","uk":"Заснування Johnson & Johnson","en":"Johnson & Johnson founded"},{"year":"1920","uk":"Поява пластиру Band-Aid","en":"Band-Aid invented"},{"year":"1959","uk":"Придбання McNeil","en":"McNeil acquisition"},{"year":"1961","uk":"Придбання Janssen Pharmaceutica","en":"Janssen Pharmaceutica acquisition"},{"year":"2017","uk":"Придбання Actelion","en":"Actelion acquisition"},{"year":"2023","uk":"Відокремлення Kenvue","en":"Kenvue separation"}]},"LLY":{"name":"Eli Lilly","year":"1876","sector":{"uk":"Фармацевтика","en":"Pharmaceuticals"},"history":{"uk":"Фармацевт Елі Ліллі заснував підприємство в Індіанаполісі. Компанія розвивала стандартизоване виробництво ліків, а у 1920-х стала піонером комерційного інсуліну.","en":"Pharmacist Eli Lilly founded the company in Indianapolis. It developed standardized medicines and pioneered commercial insulin in the 1920s."},"source":"https://www.lilly.com/","branches":{"uk":["Ліки для діабету й ожиріння","Онкологія","Імунологія","Неврологія"],"en":["Diabetes and obesity medicines","Oncology","Immunology","Neuroscience"]},"recognition":{"uk":"Раннє виробництво інсуліну стало важливою історичною віхою. Prozac, а пізніше препарати tirzepatide (Mounjaro та Zepbound), привернули значну увагу до компанії.","en":"Early insulin manufacturing was a major historical milestone. Prozac and later tirzepatide medicines (Mounjaro and Zepbound) attracted substantial attention."},"milestones":[{"year":"1876","uk":"Заснування Eli Lilly","en":"Eli Lilly founded"},{"year":"1923","uk":"Комерційний інсулін","en":"Commercial insulin"},{"year":"1982","uk":"Схвалення людського інсуліну Humulin","en":"Human insulin Humulin approved"},{"year":"1987","uk":"Prozac","en":"Prozac"},{"year":"2022","uk":"Mounjaro","en":"Mounjaro"},{"year":"2023","uk":"Схвалення Zepbound у США","en":"US Zepbound approval"}]},"NVO":{"name":"Novo Nordisk","year":"1923 / 1989","sector":{"uk":"Фармацевтика","en":"Pharmaceuticals"},"history":{"uk":"Історія почалася з виробництва інсуліну у Данії в 1923 році. У 1989 році Novo та Nordisk об'єдналися в сучасну компанію, що спеціалізується на лікуванні хронічних захворювань.","en":"Its history began with insulin production in Denmark in 1923. Novo and Nordisk merged in 1989 to form the modern company focused on chronic disease treatment."},"source":"https://www.novonordisk.com/about/our-heritage.html","branches":{"uk":["Інсулін","GLP-1 препарати","Лікування рідкісних захворювань"],"en":["Insulin","GLP-1 medicines","Rare disease treatments"]},"recognition":{"uk":"Досвід у виробництві інсуліну сформував спеціалізацію Novo Nordisk. Ozempic і Wegovy значно підвищили суспільну увагу до компанії та лікування діабету й ожиріння.","en":"Insulin expertise established Novo Nordisk's specialization. Ozempic and Wegovy greatly increased public attention to the company and diabetes and obesity treatment."},"milestones":[{"year":"1923","uk":"Початок виробництва інсуліну в Nordisk","en":"Nordisk insulin production begins"},{"year":"1925","uk":"Заснування Novo","en":"Novo founded"},{"year":"1989","uk":"Злиття Novo та Nordisk","en":"Novo and Nordisk merger"},{"year":"2010","uk":"Схвалення Victoza у США","en":"US Victoza approval"},{"year":"2017","uk":"Схвалення Ozempic у США","en":"US Ozempic approval"},{"year":"2021","uk":"Схвалення Wegovy у США","en":"US Wegovy approval"}]},"KO":{"name":"Coca-Cola","year":"1886 / 1892","sector":{"uk":"Напої","en":"Beverages"},"history":{"uk":"Джон Пембертон створив напій Coca-Cola у 1886 році. У 1892 році засновано The Coca-Cola Company, яка розвинула глобальну систему виробництва та розливу.","en":"John Pemberton created Coca-Cola in 1886. The Coca-Cola Company was founded in 1892 and developed a global production and bottling system."},"source":"https://www.coca-colacompany.com/","branches":{"uk":["Газовані напої","Вода та спортивні напої","Концентрати й партнерства з розливу"],"en":["Soft drinks","Water and sports drinks","Concentrates and bottling partnerships"]},"recognition":{"uk":"Впізнаваність Coca-Cola сформували смак напою, фірмова пляшка, реклама та міжнародна система розливу. Модель концентратів і партнерів дозволила розширювати дистрибуцію.","en":"Coca-Cola's taste, signature bottle, advertising and international bottling system built brand recognition. Its concentrate-and-partner model expanded distribution."},"milestones":[{"year":"1886","uk":"Перший напій Coca-Cola","en":"First Coca-Cola drink"},{"year":"1892","uk":"Створення The Coca-Cola Company","en":"The Coca-Cola Company founded"},{"year":"1915","uk":"Дизайн контурної пляшки","en":"Contour bottle design"},{"year":"1919","uk":"Вихід на біржу","en":"IPO"},{"year":"1982","uk":"Запуск Diet Coke","en":"Diet Coke launch"},{"year":"2005","uk":"Запуск Coca-Cola Zero","en":"Coca-Cola Zero launch"}]},"PEP":{"name":"PepsiCo","year":"1898 / 1965","sector":{"uk":"Напої та продукти","en":"Food and beverages"},"history":{"uk":"Напій Pepsi-Cola отримав свою назву у 1898 році. У 1965 році Pepsi-Cola і Frito-Lay об'єдналися, утворивши PepsiCo — групу напоїв та снеків.","en":"Pepsi-Cola adopted its name in 1898. In 1965 Pepsi-Cola and Frito-Lay merged to create PepsiCo, a beverage and snack group."},"source":"https://www.pepsico.com/","branches":{"uk":["Pepsi та інші напої","Lay’s і Doritos","Quaker та продукти харчування"],"en":["Pepsi and other drinks","Lay’s and Doritos","Quaker and foods"]},"recognition":{"uk":"Поєднання напоїв і снеків після злиття з Frito-Lay створило широку дистрибуцію. Pepsi Challenge, музичний маркетинг та бренди Lay’s і Doritos посилили впізнаваність.","en":"Combining beverages and snacks after the Frito-Lay merger created broad distribution. Pepsi Challenge, music marketing and Lay’s and Doritos strengthened recognition."},"milestones":[{"year":"1898","uk":"Назва Pepsi-Cola","en":"Pepsi-Cola name adopted"},{"year":"1965","uk":"Створення PepsiCo","en":"PepsiCo formed"},{"year":"1975","uk":"Pepsi Challenge","en":"Pepsi Challenge"},{"year":"1998","uk":"Придбання Tropicana","en":"Tropicana acquisition"},{"year":"2001","uk":"Quaker Oats","en":"Quaker Oats"}]},"MCD":{"name":"McDonald's","year":"1940 / 1955","sector":{"uk":"Ресторани","en":"Restaurants"},"history":{"uk":"Брати Річард і Моріс Макдональди відкрили ресторан у 1940 році та розробили швидку систему обслуговування. Рей Крок розпочав розширення франшизи у 1955 році.","en":"Richard and Maurice McDonald opened a restaurant in 1940 and developed a fast-service system. Ray Kroc began expanding the franchise in 1955."},"source":"https://corporate.mcdonalds.com/","branches":{"uk":["Ресторани","Франчайзинг","Ліцензування та ресторанна нерухомість"],"en":["Restaurants","Franchising","Licensing and restaurant real estate"]},"recognition":{"uk":"Стандартизоване швидке обслуговування, франшизи, золоті арки й Big Mac створили впізнаваний глобальний формат. Єдині процеси допомогли масштабувати мережу.","en":"Standardized fast service, franchising, the Golden Arches and Big Mac created a recognizable global format. Consistent processes helped scale the chain."},"milestones":[{"year":"1940","uk":"Перший ресторан братів Макдональдів","en":"McDonald brothers open first restaurant"},{"year":"1948","uk":"Speedee Service System","en":"Speedee Service System"},{"year":"1955","uk":"Франчайзинг Рея Крока","en":"Ray Kroc's franchise expansion"},{"year":"1965","uk":"IPO","en":"IPO"},{"year":"1968","uk":"Національний запуск Big Mac у США","en":"US national Big Mac launch"},{"year":"1979","uk":"Happy Meal у США","en":"US Happy Meal launch"}]},"WMT":{"name":"Walmart","year":"1962","sector":{"uk":"Роздрібна торгівля","en":"Retail"},"history":{"uk":"Сем Волтон відкрив перший Walmart у Роджерсі, Арканзас. Модель доступних цін, масштабної логістики та магазинів великого формату стала основою розширення.","en":"Sam Walton opened the first Walmart in Rogers, Arkansas. Low prices, large-scale logistics and big-format stores drove its expansion."},"source":"https://corporate.walmart.com/","branches":{"uk":["Walmart магазини","Електронна торгівля","Sam’s Club","Логістика"],"en":["Walmart stores","E-commerce","Sam’s Club","Logistics"]},"recognition":{"uk":"Низькі ціни, масштабні закупівлі й ефективна логістика стали основою моделі Walmart. Великі магазини та подальша онлайн-торгівля розширили охоплення.","en":"Low prices, purchasing scale and efficient logistics underpin Walmart's model. Large stores and later online commerce broadened its reach."},"milestones":[{"year":"1962","uk":"Перший Walmart","en":"First Walmart"},{"year":"1969","uk":"Реєстрація Walmart як корпорації","en":"Walmart incorporated"},{"year":"1970","uk":"IPO","en":"IPO"},{"year":"1983","uk":"Sam’s Club","en":"Sam’s Club"},{"year":"1988","uk":"Supercenter","en":"Supercenter"},{"year":"1991","uk":"Перший міжнародний магазин у Мексиці","en":"First international store in Mexico"},{"year":"2018","uk":"Придбання контрольного пакета Flipkart","en":"Controlling stake in Flipkart acquired"}]},"COST":{"name":"Costco","year":"1983","sector":{"uk":"Роздрібна торгівля","en":"Retail"},"history":{"uk":"Перший Costco відкрився у Сіетлі у 1983 році, продовживши модель складів-магазинів з членством. У 1993 році компанія об'єдналася з Price Club, заснованим у 1976 році.","en":"The first Costco opened in Seattle in 1983, building on the membership warehouse model. It merged in 1993 with Price Club, founded in 1976."},"source":"https://www.costco.com/","branches":{"uk":["Складські магазини","Членські внески","Kirkland Signature"],"en":["Warehouse stores","Membership fees","Kirkland Signature"]},"recognition":{"uk":"Обмежений асортимент, великі упаковки й членська модель дозволили Costco зосередитися на ціні. Kirkland Signature стала впізнаваною власною маркою.","en":"Limited selection, bulk packages and a membership model allowed Costco to focus on value. Kirkland Signature became a recognizable private label."},"milestones":[{"year":"1976","uk":"Відкриття Price Club","en":"Price Club opens"},{"year":"1983","uk":"Перший Costco","en":"First Costco"},{"year":"1985","uk":"IPO Costco","en":"Costco IPO"},{"year":"1993","uk":"Злиття з Price Club","en":"Price Club merger"},{"year":"1995","uk":"Kirkland Signature","en":"Kirkland Signature"}]},"DIS":{"name":"Disney","year":"1923","sector":{"uk":"Медіа та розваги","en":"Media and entertainment"},"history":{"uk":"Волт і Рой Діснеї заснували анімаційну студію. Mickey Mouse (1928), повнометражна анімація та Disneyland (1955) стали основою ширшого медіабізнесу.","en":"Walt and Roy Disney founded an animation studio. Mickey Mouse (1928), feature animation and Disneyland (1955) laid the foundations for a wider media business."},"source":"https://thewaltdisneycompany.com/","branches":{"uk":["Кіно й анімація","Тематичні парки","Телебачення та спорт","Стримінг"],"en":["Film and animation","Theme parks","Television and sports","Streaming"]},"recognition":{"uk":"Mickey Mouse, анімаційні фільми та Disneyland зробили Disney глобальним брендом. Pixar, Marvel і Star Wars розширили бібліотеку персонажів та історій.","en":"Mickey Mouse, animated films and Disneyland made Disney a global brand. Pixar, Marvel and Star Wars expanded its character and story library."},"milestones":[{"year":"1923","uk":"Заснування Disney Brothers Cartoon Studio","en":"Disney Brothers Cartoon Studio founded"},{"year":"1928","uk":"Mickey Mouse","en":"Mickey Mouse"},{"year":"1937","uk":"«Білосніжка та семеро гномів»","en":"Snow White and the Seven Dwarfs"},{"year":"1955","uk":"Disneyland","en":"Disneyland"},{"year":"1971","uk":"Відкриття Walt Disney World","en":"Walt Disney World opens"},{"year":"2006","uk":"Pixar","en":"Pixar"},{"year":"2012","uk":"Придбання Lucasfilm","en":"Lucasfilm acquisition"},{"year":"2019","uk":"Disney+","en":"Disney+"}]},"SONY":{"name":"Sony","year":"1946","sector":{"uk":"Електроніка та розваги","en":"Electronics and entertainment"},"history":{"uk":"Масару Ібука й Акіо Моріта заснували Tokyo Tsushin Kogyo. Транзисторні радіоприймачі, Walkman і PlayStation стали важливими етапами розвитку Sony.","en":"Masaru Ibuka and Akio Morita founded Tokyo Tsushin Kogyo. Transistor radios, Walkman and PlayStation were important milestones for Sony."},"source":"https://www.sony.com/","branches":{"uk":["PlayStation","Музика й кіно","Сенсори зображень","Електроніка"],"en":["PlayStation","Music and film","Image sensors","Electronics"]},"recognition":{"uk":"Транзисторні радіоприймачі, Walkman і PlayStation стали культовими продуктами Sony. Поєднання електроніки з розважальним контентом сформувало широку впізнаваність.","en":"Transistor radios, Walkman and PlayStation became iconic Sony products. Combining electronics with entertainment content built broad recognition."},"milestones":[{"year":"1946","uk":"Заснування Tokyo Tsushin Kogyo","en":"Tokyo Tsushin Kogyo founded"},{"year":"1955","uk":"Транзисторний радіоприймач TR-55","en":"TR-55 transistor radio"},{"year":"1958","uk":"Назва Sony Corporation","en":"Sony Corporation name adopted"},{"year":"1979","uk":"Walkman","en":"Walkman"},{"year":"1989","uk":"Придбання Columbia Pictures","en":"Columbia Pictures acquisition"},{"year":"1994","uk":"PlayStation","en":"PlayStation"},{"year":"2000","uk":"PlayStation 2","en":"PlayStation 2"},{"year":"2020","uk":"PlayStation 5","en":"PlayStation 5"}]},"SAP":{"name":"SAP","year":"1972","sector":{"uk":"Корпоративне ПЗ","en":"Enterprise software"},"history":{"uk":"П'ятеро колишніх співробітників IBM заснували SAP у Німеччині для створення інтегрованого бізнес-ПЗ. Системи R/2, R/3 та пізніше S/4HANA розвинули цей напрям.","en":"Five former IBM employees founded SAP in Germany to build integrated business software. R/2, R/3 and later S/4HANA advanced that business."},"source":"https://www.sap.com/","branches":{"uk":["ERP","S/4HANA","Хмарні бізнес-застосунки","Аналітика"],"en":["ERP","S/4HANA","Cloud business applications","Analytics"]},"recognition":{"uk":"SAP стала відомою завдяки інтеграції фінансів, логістики й виробництва в єдині корпоративні системи. R/3 та S/4HANA стали ключовими платформами розвитку.","en":"SAP became known for integrating finance, logistics and production into enterprise systems. R/3 and S/4HANA became key platforms in its development."},"milestones":[{"year":"1972","uk":"Заснування SAP","en":"SAP founded"},{"year":"1979","uk":"SAP R/2","en":"SAP R/2"},{"year":"1988","uk":"IPO","en":"IPO"},{"year":"1992","uk":"R/3","en":"R/3"},{"year":"2010","uk":"Придбання Sybase","en":"Sybase acquisition"},{"year":"2015","uk":"S/4HANA","en":"S/4HANA"}]},"CAT":{"name":"Caterpillar","year":"1925","sector":{"uk":"Промислове обладнання","en":"Industrial machinery"},"history":{"uk":"Holt Manufacturing та C. L. Best Tractor об'єдналися у 1925 році. Компанія розвинула гусеничні трактори, будівельну техніку та промислові двигуни.","en":"Holt Manufacturing and C. L. Best Tractor merged in 1925. The company expanded into tracked tractors, construction equipment and industrial engines."},"source":"https://www.caterpillar.com/","branches":{"uk":["Будівельна техніка","Гірниче обладнання","Двигуни й енергетика","Сервіс"],"en":["Construction machinery","Mining equipment","Engines and power","Services"]},"recognition":{"uk":"Гусеничні трактори, важка техніка та дилерська мережа сформували впізнаваність Caterpillar. Жовтий колір і марка CAT стали символами промислового обладнання.","en":"Tracked tractors, heavy machinery and its dealer network established Caterpillar's reputation. The yellow color and CAT brand became symbols of industrial equipment."},"milestones":[{"year":"1904","uk":"Перший успішний гусеничний трактор Holt","en":"Holt's successful tracked tractor"},{"year":"1925","uk":"Злиття Holt та Best","en":"Holt and Best merger"},{"year":"1931","uk":"Перший дизельний трактор Caterpillar","en":"First Caterpillar diesel tractor"},{"year":"1950","uk":"Створення першої закордонної дочірньої компанії у Великій Британії","en":"First overseas subsidiary established in the UK"},{"year":"2011","uk":"Придбання Bucyrus","en":"Bucyrus acquisition"}]},"CSCO":{"name":"Cisco","year":"1984","sector":{"uk":"Мережеве обладнання","en":"Networking"},"history":{"uk":"Леонард Босак і Сенді Лернер створили Cisco для мережевого з'єднання комп'ютерів. Маршрутизатори стали основою бізнесу, який розширився до комутаторів, безпеки та зв'язку.","en":"Leonard Bosack and Sandy Lerner founded Cisco to connect computers across networks. Routers drove growth into switching, security and communications."},"source":"https://www.cisco.com/","branches":{"uk":["Маршрутизатори й комутатори","Кібербезпека","Webex","Спостережуваність мереж"],"en":["Routers and switches","Cybersecurity","Webex","Network observability"]},"recognition":{"uk":"Cisco зросла разом із поширенням інтернету: її маршрутизатори та комутатори з’єднували корпоративні мережі. Сертифікації Cisco також посилили впізнаваність серед ІТ-фахівців.","en":"Cisco grew alongside the internet as its routers and switches connected enterprise networks. Cisco certifications also strengthened recognition among IT professionals."},"milestones":[{"year":"1984","uk":"Заснування Cisco","en":"Cisco founded"},{"year":"1990","uk":"IPO","en":"IPO"},{"year":"1993","uk":"Придбання Crescendo Communications","en":"Crescendo Communications acquisition"},{"year":"2007","uk":"Придбання WebEx","en":"WebEx acquisition"},{"year":"2017","uk":"Придбання AppDynamics","en":"AppDynamics acquisition"},{"year":"2024","uk":"Придбання Splunk","en":"Splunk acquisition"}]}};
const t=(uk,en)=>document.documentElement.lang==='en'?en:uk;
const el=(tag,cls,text)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x;};
const assetRoot=new URL('.',document.currentScript.src);
let dialog,selected,opener,logoPromise;function getLocalLogos(){return logoPromise||(logoPromise=fetch(new URL('stock-logos.json',assetRoot)).then(r=>r.ok?r.json():{}).catch(()=>({})));}
function ensure(){if(dialog)return;dialog=el('dialog','company-dialog');dialog.setAttribute('aria-labelledby','company-dialog-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus({preventScroll:true});});new MutationObserver(()=>{if(dialog.open)render();}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});}
function visual(symbol,name,logo){
 const side=el('aside','company-side');const frame=el('div','company-banner');const fallback=el('div','company-banner-fallback',name);frame.append(fallback);
 getLocalLogos().then(map=>{const paths=window.NbuLogos.candidates('stock',symbol,map[symbol]);if(logo&&paths.includes(logo)){paths.splice(paths.indexOf(logo),1);paths.unshift(logo);}function next(){const path=paths.shift();if(!path)return;const im=el('img','company-banner-logo');im.alt=name;im.width=160;im.height=100;im.decoding='async';im.referrerPolicy='no-referrer';im.addEventListener('load',()=>{if(im.naturalWidth)frame.replaceChildren(im);else next();},{once:true});im.addEventListener('error',()=>{window.NbuLogos.fail(path);next();},{once:true});im.src=path;}next();});
 side.append(frame);const caption=el('div','company-banner-caption');caption.append(el('span','',t('Інструмент','Instrument')),el('strong','',symbol));side.append(caption);return side;
}
function section(title,text){const block=el('section','company-detail');block.append(el('h3','company-subtitle',title),el('p','company-history',text));return block;}
function render(){const {symbol,name,logo,quote}=selected,p=Object.hasOwn(profiles,symbol)?profiles[symbol]:null,lang=document.documentElement.lang==='en'?'en':'uk',companyName=p?.name||name||symbol;dialog.replaceChildren();
 const panel=el('div','company-panel'),head=el('header','company-head'),identity=el('div','company-identity');const title=el('h2','',companyName);title.id='company-dialog-title';identity.append(el('span','company-eyebrow',t('Про компанію','Company profile')),title,el('p','company-ticker',symbol+(quote?' · '+quote:'')));
 const close=el('button','company-close');close.type='button';close.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18"/></svg>';close.setAttribute('aria-label',t('Закрити','Close'));close.addEventListener('click',()=>dialog.close());head.append(identity,close);panel.append(head);
 const top=el('div','company-overview'),main=el('div','company-main'),rail=el('div','company-rail');rail.append(visual(symbol,companyName,logo));
 if(p){const facts=el('div','company-facts');for(const [label,value] of [[t('Витоки / заснування','Origins / founded'),p.year],[t('Галузь','Industry'),p.sector[lang]]]){const f=el('div','company-fact');f.append(el('small','',label),el('strong','',value));facts.append(f);}main.append(facts,section(t('Як усе починалося','How it started'),p.history[lang]),section(t('Що зробило компанію відомою','What made the company recognizable'),p.recognition[lang]));
 const branches=el('section','company-branches');branches.append(el('h3','company-subtitle',t('Основні напрями бізнесу','Main business areas')));const list=el('ul','company-branch-list');for(const item of p.branches[lang])list.append(el('li','',item));branches.append(list);rail.append(branches);
 }else{main.append(el('p','company-history',t('Історична довідка для цього інструмента ще готується.','A historical profile for this instrument is not available yet.')));}
 top.append(main,rail);panel.append(top);
 if(p){const timeline=el('section','company-timeline');timeline.append(el('h3','company-subtitle',t('Ключові етапи розвитку','Key milestones')));const list=el('ol','company-timeline-list');for(const item of p.milestones){const li=el('li','company-event');li.append(el('strong','company-year',item.year),el('span','company-event-label',item[lang]));list.append(li);}timeline.append(list);top.append(timeline);const footer=el('footer','company-footer');const note=el('span','company-profile-note',t('Історична довідка · не інвестиційна рекомендація','Historical overview · not investment advice'));const a=el('a','company-source',t('Офіційний сайт / джерело','Official website / source'));a.href=p.source;a.target='_blank';a.rel='noopener noreferrer';a.append(el('span','company-external','↗'));footer.append(note,a);panel.append(footer);}
 dialog.append(panel);
}
function open(symbol,name,logo,quote){if(!/^[A-Z0-9][A-Z0-9.=-]{0,23}$/.test(symbol||''))return;ensure();opener=document.activeElement;selected={symbol,name,logo,quote};render();if(!dialog.open)dialog.showModal();dialog.querySelector('.company-close').focus({preventScroll:true});}
function button(symbol,name,logo,quote){const b=el('button','company-info-button',t('Про компанію','About company'));b.type='button';b.addEventListener('click',()=>open(symbol,name,typeof logo==='function'?logo():logo,quote));return b;}
window.NbuCompany={open,button,profiles};})();
